namespace sv_7a86e615909a4e2187e47e4093af9dcf.Services;

public sealed class RecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with fresh mozzarella, tomatoes, and basil.", 30),
            new(2, "Risotto alla Milanese", "Creamy saffron risotto from Milan, finished with Parmigiano-Reggiano.", 45),
            new(3, "Tiramisu", "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", 25),
        },
        [2] = new List<Recipe>
        {
            new(4, "Tacos al Pastor", "Marinated pork tacos with pineapple, onion, and cilantro.", 40),
            new(5, "Guacamole", "Fresh avocado dip with lime, jalapeño, and tomato.", 10),
            new(6, "Churros", "Fried dough pastry coated in cinnamon sugar, served with chocolate sauce.", 35),
        },
        [3] = new List<Recipe>
        {
            new(7, "Sushi Rolls", "Vinegared rice and fresh fish wrapped in nori seaweed.", 50),
            new(8, "Ramen", "Rich pork-bone broth with wheat noodles, chashu, and soft-boiled egg.", 60),
            new(9, "Mochi", "Sweet rice cake filled with red bean paste.", 20),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_7a86e615909a4e2187e47e4093af9dcf.Services
@using Microsoft.AspNetCore.Components
@inject RecipeService RecipeService
@inject ILogger<Recipes> Logger
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h3>Recipes — Cuisine #@CuisineId</h3>

<div class="mb-3">
    <label class="form-label fw-semibold">Sort:</label>
    <a href="/recipes/@CuisineId?sort=newest"
       class="btn btn-sm @(Sort == "newest" ? "btn-primary" : "btn-outline-primary") me-1">Newest</a>
    <a href="/recipes/@CuisineId?sort=popular"
       class="btn btn-sm @(Sort == "popular" ? "btn-primary" : "btn-outline-primary")">Popular</a>
</div>

@if (_error is not null)
{
    <div class="alert alert-danger d-flex align-items-center" role="alert">
        <span class="me-auto">@_error</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else
{
    @if (_isRefreshing)
    {
        <div class="d-flex align-items-center gap-2 mb-3 text-muted small">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <span>Refreshing…</span>
        </div>
    }

    var displayed = Sort == "popular"
        ? _recipes.OrderByDescending(r => r.PrepTimeMinutes).ToList()
        : _recipes.OrderByDescending(r => r.Id).ToList();

    <div class="row row-cols-1 row-cols-md-3 g-3">
        @foreach (var recipe in displayed)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        Prep: @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>

    @if (displayed.Count == 0)
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;

    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        NormalizeSort();

        // Only reload when the cuisine changes, not when sort changes.
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request.
        await CancelPendingLoadAsync();

        _cts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        var token = _cts.Token;

        _error = null;
        _isRefreshing = _recipes is not null;
        var targetCuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(targetCuisineId, token);

            token.ThrowIfCancellationRequested();

            _recipes = result;
            _loadedCuisineId = targetCuisineId;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Intentional cancellation — nothing to do.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", targetCuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", targetCuisineId);
            _error = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private async Task CancelPendingLoadAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    private void NormalizeSort()
    {
        if (!string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            && !string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase))
        {
            Sort = "newest";
        }
    }

    // Master token cancelled on dispose to stop all work.
    private readonly CancellationTokenSource _disposeCts = new();

    public void Dispose()
    {
        _disposeCts.Cancel();
        _cts?.Dispose();
        _disposeCts.Dispose();
    }
}

