+        _error = null;
+        _isRefreshing = _recipes is not null;
+        var targetCuisineId = CuisineId;
+
+        try
+        {
+            var result = await RecipeService.GetByCuisineAsync(targetCuisineId, token);
+
+            token.ThrowIfCancellationRequested();
+
+            _recipes = result;
+            _loadedCuisineId = targetCuisineId;
+        }
+        catch (OperationCanceledException) when (token.IsCancellationRequested)
+        {
+            // Intentional cancellation — nothing to do.
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", targetCuisineId);
+            _error = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", targetCuisineId);
+            _error = "Something went wrong while loading recipes. Please try again.";
+        }
+        finally
+        {
+            _isRefreshing = false;
+        }
+    }
+
+    private async Task Retry()
+    {
+        await LoadRecipesAsync();
+    }
+
+    private async Task CancelPendingLoadAsync()
+    {
+        if (_cts is not null)
+        {
+            await _cts.CancelAsync();
+            _cts.Dispose();
+            _cts = null;
+        }
+    }
+
+    private void NormalizeSort()
+    {
+        if (!string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
+            && !string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase))
+        {
+            Sort = "newest";
+        }
+    }
+
+    // Master token cancelled on dispose to stop all work.
+    private readonly CancellationTokenSource _disposeCts = new();
+
+    public void Dispose()
+    {
+        _disposeCts.Cancel();
+        _cts?.Dispose();
+        _disposeCts.Dispose();
+    }
